from modules.byte_program import _geom_sum
import random
M=(1<<64)-1
def gs(q,n):
 # recursive binary
 if n==0:return (1,0)
 if n%2==0:
  p,s=gs(q,n//2);return (p*p)&M,(s*(1+p))&M
 else:
  p,s=gs(q,n-1);return (p*q)&M,(s+p)&M
for _ in range(1000):
 q=random.randrange(1<<64);n=random.randrange(0,1<<63)
 assert _geom_sum(q,n)==gs(q,n)[1],(q,n)
print('geom huge ok')
